import json
def transform(g):
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    seen=[[False]*w for _ in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]==5 and not seen[i][j]:
                comp=[]; st=[(i,j)]; seen[i][j]=True
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                        if 0<=x<h and 0<=y<w and g[x][y]==5 and not seen[x][y]:
                            seen[x][y]=True; st.append((x,y))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                top,bot,l,r=min(rs),max(rs),min(cs),max(cs)
                holes=[(x,y) for x in range(top,bot+1) for y in range(l,r+1) if g[x][y]==0]
                for x,y in holes: g[x][y]=2
                if top>0:
                    gap=holes[0][1]
                    left = any(y<gap for x,y in holes)
                    y=gap
                    while 0<=y<w:
                        g[top-1][y]=2
                        y += -1 if left else 1
    return g
